const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = (v = '') => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 check:'m5 12 4 4L19 6', tasks:'M9 6h12M9 12h12M9 18h12M3 6h.01M3 12h.01M3 18h.01',
 shift:'M9 3H5v18h14V3h-4M9 2h6v4H9zM9 11h6M9 16h6', team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 chart:'M4 3v18h17M9 16v-5M14 16V6M19 16V9', report:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',
 search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-5-5 5 5-5 5', chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6', moon:'M21 12.8A9 9 0 0 1 11.2 3 9 9 0 1 0 21 12.8', sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1', bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4', panel:'M3 3h18v18H3zM9 3v18', close:'m6 6 12 12M6 18 18 6', clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5', filter:'M4 6h16M7 12h10M10 18h4', file:'M14 2H5v20h14V7zM14 2v6h5', logout:'M9 3H3v18h6M10 12h11m-5-5 5 5-5 5', dots:'M5 12h.01M12 12h.01M19 12h.01', mail:'M3 5h18v14H3zM3 5l9 7 9-7', brief:'M3 7h18v14H3zM8 7V3h8v4M3 12h18', flag:'M5 21V3h13l-3 5 3 5H5', link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2', alert:'M12 3 2 21h20zM12 9v5M12 18h.01', calendar:'M3 5h18v16H3zM7 3v4M17 3v4M3 10h18', spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.grid}"/></svg>`;
const btn = (label, action, cls='', ico='') => `<button type="button" class="button ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const opt = (items, value, all) => (all !== undefined ? `<option value="">${all}</option>`:'') + items.map(x=>`<option value="${esc(typeof x==='object'?x.id:x)}" ${String(typeof x==='object'?x.id:x)===String(value)?'selected':''}>${esc(typeof x==='object'?x.name:x)}</option>`).join('');
const field = (label, input, cls='') => `<label class="field ${cls}"><span>${label}</span>${input}</label>`;
const input = (name, value='', type='text', extra='') => `<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const select = (name, items, value, all) => `<select name="${name}">${opt(items,value,all)}</select>`;
const initials = name => name.split(' ').map(s=>s[0]).slice(0,2).join('');
const avatar = (u, size='') => `<span class="avatar ${size} tone-${(u?.id||1)%5}">${initials(u?.name||'Unknown')}</span>`;
const person = id => (S.people||S.users).find(x=>x.id===Number(id)) || {id:0,name:'Employee',role:'',team:''};
const status = s => `<span class="status status-${s.toLowerCase().replaceAll(' ','-')}"><i></i>${esc(s)}</span>`;
const priority = p => `<span class="priority p-${p.toLowerCase()}"><span>${({Low:'▁',Normal:'▂',High:'▥',Critical:'!'})[p]}</span>${p}</span>`;
const complexity = c => `<span class="complexity" title="${c}">${[0,1,2,3].map(i=>`<i class="${i<S.complexities.indexOf(c)+1?'filled':''}"></i>`).join('')}<span>${c}</span></span>`;
const fmt = d => d?new Date(d+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric'}):'—';
const fullDate = d => new Date(d+'T12:00:00').toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
let S, route = location.hash.slice(1)||'dashboard', collapsed=localStorage.getItem('cadence-collapsed')==='1', taskFilter={q:'',status:'',priority:'',sort:'deadline',scope:'all'}, columns=new Set(['assignee','status','priority','complexity','deadline','hours','quality']), page=1, detail=null, activeShift=null, period='This Month', employeeId=null, reportType='Employee Monthly Report', range={start:'',end:''}, reportFilters={employee:'',team:'',status:'',complexity:'',quality:'',q:''}, previousFocus=null;
document.documentElement.dataset.theme=localStorage.getItem('cadence-theme')||'dark';
async function api(path,method='GET',data){
  const r=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Cadence-Request':'1'},body:data===undefined?undefined:JSON.stringify(data)});
  const value=await r.json(); if(!r.ok){if(r.status===401 && path!=='login') login();throw new Error(value.error||'Something went wrong. Please retry.');}return value;
}
function toast(message,error=false){const t=$('#toast');t.innerHTML=`${icon(error?'alert':'check')}<span>${esc(message)}</span>`;t.className=`visible ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500);}
async function refresh(renderPage=true){S=await api('state');if(!range.start) setRange();if(renderPage) render();}
function navigate(to){route=to;location.hash=to;page=1;taskFilter={q:'',status:'',priority:'',sort:'deadline',scope:'all'};closeOverlay();render();}
function setRange(){const d=new Date((S?.today||new Date().toISOString().slice(0,10))+'T12:00:00');let start=new Date(d.getFullYear(),d.getMonth(),1,12),end=d;if(period==='Last Month'){start=new Date(d.getFullYear(),d.getMonth()-1,1,12);end=new Date(d.getFullYear(),d.getMonth(),0,12);}if(period==='Quarter')start=new Date(d.getFullYear(),Math.floor(d.getMonth()/3)*3,1,12);const iso=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;range={start:iso(start),end:iso(end)};}
const inRange = d => d>=range.start && d<=range.end;
const activeTasks = ts => ts.filter(t=>!['Done','Cancelled'].includes(t.status));
const overdue = t => t.deadline && t.deadline<S.today && !['Done','Cancelled'].includes(t.status);
const sectionHead = (title,meta='',action='') => `<div class="section-head"><div><h2>${title}</h2>${meta?`<p>${meta}</p>`:''}</div>${action}</div>`;
const empty = (title,description='',action='') => `<div class="empty">${icon('check')}<h3>${title}</h3><p>${description}</p>${action}</div>`;
function login(){S=null;$('#overlay').innerHTML='';$('#app').innerHTML=`<main class="login"><section class="login-story"><a class="brand"><span class="brand-mark">${icon('chart')}</span>cadence<span class="brand-dot">.</span></a><div><span class="eyebrow">YOUR TEAM. IN SYNC.</span><h1>Good work deserves<br>a clearer view.</h1><p>A considered workspace for the people behind<br>security operations.</p><div class="login-preview"><div class="section-head"><span>Team momentum</span><span class="positive">Steady progress ${icon('arrow')}</span></div><div class="preview-bars">${[35,49,43,64,55,78,69,90,82,100,92,110].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="muted">Less friction. More focus.</div></div></div><small>WORK MANAGEMENT · SHIFT ACTIVITY · PERFORMANCE</small></section><section class="login-form"><div class="login-box"><span class="eyebrow">WELCOME BACK</span><h2>Sign in to your workspace</h2><p class="muted">Pick up where your team left off.</p><form id="login-form">${field('Work email',input('email','','email','required autocomplete="username" placeholder="you@company.com"'))}${field('Password',input('password','','password','required autocomplete="current-password" placeholder="Enter your password"'))}<div class="form-error" role="alert"></div><button class="button primary wide" type="submit">Sign in ${icon('arrow')}</button></form><details class="demo-help"><summary>Using the local demo?</summary><p>Email: <strong>sara@cadence.local</strong><br>Password: <strong>Cadence-demo-2026!</strong></p><p>Available only when the server is started in demo mode.</p></details><p class="small muted">An internal workspace for focused teams.</p></div></section></main>`;}
const navs=[['dashboard','grid','Dashboard'],['tasks','tasks','Tasks'],['shifts','shift','Shift logs'],['team','team','Team'],['performance','chart','Performance'],['reports','report','Reports']];
function shell(){return `<div class="app-shell ${collapsed?'collapsed':''}"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('chart')}</span><span class="brand-text">cadence<span class="brand-dot">.</span></span></a><button class="workspace" data-action="workspace" title="Security Department"><span class="workspace-icon">S</span><span class="nav-label"><strong>Security Department</strong><small>Organization workspace</small></span>${icon('down')}</button><div class="nav-caption nav-label">WORKSPACE</div><nav aria-label="Main navigation">${navs.map(([id,ic,label])=>`<button data-nav="${id}" title="${label}" class="nav-item ${route.startsWith(id)?'active':''}">${icon(ic)}<span class="nav-label">${label}</span>${id==='tasks'?`<span class="nav-count nav-label">${activeTasks(S.tasks).length}</span>`:''}</button>${id==='tasks'&&route.startsWith('tasks')&&!collapsed?`<div class="subnav">${['My Tasks','Team Tasks','All Tasks'].map((n,i)=>`<button data-nav="tasks/${['my','team','all'][i]}" class="${route==='tasks/'+['my','team','all'][i]?'selected':''}">${n}</button>`).join('')}</div>`:''}`).join('')}</nav><div class="sidebar-bottom">${S.me.role==='Security Manager'?`<button class="nav-item ${route==='admin'?'active':''}" data-nav="admin" title="Administration">${icon('settings')}<span class="nav-label">Administration</span></button>`:''}<button class="nav-item" data-action="theme" title="Toggle theme">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}<span class="nav-label">${document.documentElement.dataset.theme==='dark'?'Light':'Dark'} appearance</span></button><div class="sidebar-user">${avatar(S.me)}<div class="nav-label"><strong>${esc(S.me.name)}</strong><small>${esc(S.me.role)}</small></div><button class="icon-button nav-label" data-action="logout" title="Sign out">${icon('logout')}</button></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button" data-action="collapse" aria-label="Toggle sidebar">${icon('panel')}</button><span>Workspace</span>${icon('chevron')}<strong>${route==='admin'?'Administration':navs.find(x=>route.startsWith(x[0]))?.[2]||'Dashboard'}</strong></div><div class="header-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>Search anything…</span><kbd>⌘ K</kbd></button><span class="header-divider"></span><button class="icon-button notification-dot" data-action="notifications" aria-label="Notifications">${icon('bell')}</button>${avatar(S.me,'small-avatar')}</div></header><main id="main" tabindex="-1"></main><footer class="app-footer"><span><i class="live-dot"></i>All changes saved to your workspace</span><span>Cadence ${S.demo?'· Demo workspace':''}</span></footer></div></div>`;}
function render(){if(!S)return;$('#app').innerHTML=shell();const main=$('#main');try{main.innerHTML=route.startsWith('tasks')?tasksPage():route.startsWith('shifts')?shiftsPage():route.startsWith('team')?teamPage():route.startsWith('performance')?performancePage():route==='reports'?reportsPage():route==='admin'?adminPage():dashboard();}catch(e){main.innerHTML=empty('We couldn’t load this view.','Try refreshing the workspace.',btn('Retry','retry'));console.error(e);} }
function pageHead(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`;}
function metrics(items){return `<div class="metrics-strip">${items.map(([label,value,caption,ic])=>`<div class="metric"><div class="metric-label">${label}${ic?icon(ic):''}</div><strong>${value}</strong><span>${caption}</span></div>`).join('')}</div>`;}
function dashboard(){const analyst=S.me.role==='Analyst', ts=S.tasks, active=activeTasks(ts), done=ts.filter(t=>t.status==='Done'&&t.completed.startsWith(S.today.slice(0,7))), review=ts.filter(t=>t.status==='Review'), over=ts.filter(overdue), shifts=S.shifts.filter(s=>s.day===S.today), own=shifts.find(s=>s.user_id===S.me.id), shiftDone=shifts.filter(s=>s.status==='Completed').length, soc=S.users.filter(u=>u.team.startsWith('SOC')), monthShifts=S.shifts.filter(s=>s.day.startsWith(S.today.slice(0,7))), queues=[...ts].filter(t=>overdue(t)||t.status==='Review'||t.status==='Blocked');
 return pageHead('OVERVIEW',`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${esc(S.me.name.split(' ')[0])}<span class="heading-dot">.</span>`,`${fullDate(S.today)} <span class="text-separator">/</span> Here’s your work, in focus.`,btn(analyst?(own?'Continue shift log':'Start shift log'):'View shift logs',analyst?'start-shift':'go-shifts',analyst?'primary':'','shift')+btn('Create task','create-task',analyst?'':'primary','plus'))+
 metrics([[analyst?'My active tasks':'Active tasks',active.length,`${ts.filter(t=>t.status==='In Progress').length} in progress`,'tasks'],['Awaiting review',review.length,review.length?'Ready for a closer look':'Review queue is clear','clock'],['Overdue tasks',over.length,over.length?'Needs your attention':'Everything is on track','flag'],['Completed this month',done.length,`${done.reduce((n,t)=>n+t.hours,0)} hours of focused work`,'check']])+
 `<div class="dashboard-grid"><section class="panel attention-panel">${sectionHead('Your attention, where it matters',`${queues.length} items to move forward`,btn('View all tasks','go-tasks','ghost','arrow'))}<div class="tabs"><button class="selected" data-action="queue-all">Needs attention <span>${queues.length}</span></button><button data-action="queue-review">Awaiting review <span>${review.length}</span></button></div><div id="queue">${queueRows(queues)}</div></section><section class="panel shift-summary">${sectionHead('Today’s shift coverage','The everyday work that keeps us moving.',`<span class="quiet-tag">${fmt(S.today)}</span>`)}<div class="shift-total"><strong>${shiftDone}<span> / ${soc.length}</span></strong><span>shifts completed</span></div><div class="segmented-progress">${soc.map(u=>`<i class="${shifts.find(s=>s.user_id===u.id)?.status==='Completed'?'done':shifts.find(s=>s.user_id===u.id)?'active':''}"></i>`).join('')}</div><div class="coverage-list">${soc.slice(0,5).map(u=>{const s=shifts.find(s=>s.user_id===u.id);return `<button class="person-line" data-action="${s?'open-shift:'+s.id:'employee:'+u.id}">${avatar(u,'small-avatar')}<span>${esc(u.name)}</span>${s?status(s.status):'<span class="muted small">Not started</span>'}</button>`}).join('')}</div><button class="text-link" data-nav="shifts">Open shift workspace ${icon('arrow')}</button></section><section class="panel momentum">${sectionHead('Work completed','A measured view of your team’s output.',`<span class="quiet-tag">This month</span>`)}${trendChart(ts)}<div class="chart-legend"><i></i>Completed tasks <span>Routine activities are tracked separately</span></div></section><section class="panel">${sectionHead(analyst?'My routine activity':'Routine activity','Month to date · recorded shift activity')}<div class="routine-metrics"><div><span>MISP IOCs added</span><strong>${monthShifts.reduce((n,s)=>n+s.iocs,0)}</strong></div><div><span>Tickets created</span><button class="number-link" data-action="tickets">${monthShifts.reduce((n,s)=>n+s.tickets.length,0)} ${icon('arrow')}</button></div><div><span>Shift logs completed</span><strong>${monthShifts.filter(s=>s.status==='Completed').length}</strong></div></div><div class="note">${icon('brief')}<p>Recognize the work behind the numbers.<br>Explore individual contributions in Performance.</p></div><button class="text-link" data-nav="performance">Explore performance ${icon('arrow')}</button></section></div>`;
}
function queueRows(ts){return ts.length?`<div class="queue-rows">${ts.slice(0,5).map(t=>`<button class="queue-row" data-action="task:${t.id}"><span class="queue-symbol ${overdue(t)?'danger':''}">${icon(overdue(t)?'clock':'tasks')}</span><span class="queue-title"><strong>${esc(t.title)}</strong><small><span class="mono">TSK-${String(t.id).padStart(3,'0')}</span> · ${esc(person(t.assignee).team)}</small></span><span class="queue-status">${status(t.status)}</span><span class="due ${overdue(t)?'danger':''}">${overdue(t)?'Overdue':fmt(t.deadline)}</span>${avatar(person(t.assignee),'small-avatar')}</button>`).join('')}</div>`:empty('You’re all caught up.','There’s nothing waiting for your attention.');}
function trendChart(ts){const d=new Date(S.today+'T12:00:00'), points=Array.from({length:4},(_,i)=>({label:`Week ${i+1}`,value:ts.filter(t=>t.status==='Done'&&t.completed?.startsWith(S.today.slice(0,7))&&Math.min(3,Math.floor((Number(t.completed.slice(-2))-1)/7))===i).length})), max=Math.max(4,...points.map(p=>p.value));return `<div class="trend-chart"><div class="chart-axis">${[max,Math.round(max/2),0].map(n=>`<span>${n}</span>`).join('')}</div><div class="chart-bars">${points.map(p=>`<div class="chart-column"><div class="bar-space"><span class="bar-value">${p.value}</span><i style="height:${Math.max(2,p.value/max*112)}px" title="${p.label}: ${p.value} tasks"></i></div><span>${p.label}</span></div>`).join('')}</div></div>`;}
function tasksPage(){let scope=route.split('/')[1]||'all';return pageHead('TASK MANAGEMENT',scope==='my'?'My tasks':scope==='team'?'Team tasks':'All tasks','A clear view of what’s next, what’s moving, and what’s done.',btn('Create task','create-task','primary','plus'))+`<div class="view-tabs">${['My Tasks','Team Tasks','All Tasks'].map((n,i)=>`<button data-nav="tasks/${['my','team','all'][i]}" class="${scope===['my','team','all'][i]?'selected':''}">${n}</button>`).join('')}<span>${S.tasks.length} tasks in your workspace</span></div><section class="panel task-panel"><div class="filter-bar"><label class="search-input">${icon('search')}<input id="task-search" placeholder="Search tasks…" value="${esc(taskFilter.q)}" aria-label="Search tasks"></label><select id="task-status" aria-label="Filter status">${opt(S.statuses,taskFilter.status,'All statuses')}</select><select id="task-priority" aria-label="Filter priority">${opt(S.priorities,taskFilter.priority,'All priorities')}</select>${btn('Reset','reset-task-filters','ghost')}<div class="push"></div>${btn('Columns','columns','','filter')}</div><div id="task-results">${taskResults()}</div></section>`;}
function filteredTasks(){const scope=route.split('/')[1]||'all';return S.tasks.filter(t=>(scope!=='my'||t.assignee===S.me.id)&&(scope!=='team'||person(t.assignee).team===S.me.team)&&(!taskFilter.status||t.status===taskFilter.status)&&(!taskFilter.priority||t.priority===taskFilter.priority)&&(`${t.title} TSK-${String(t.id).padStart(3,'0')} ${person(t.assignee).name}`.toLowerCase().includes(taskFilter.q.toLowerCase()))).sort((a,b)=>String(a[taskFilter.sort]||'zzz').localeCompare(String(b[taskFilter.sort]||'zzz')));}
function taskResults(){const ts=filteredTasks(),pages=Math.max(1,Math.ceil(ts.length/10));page=Math.min(page,pages);return taskTable(ts.slice((page-1)*10,page*10))+`<div class="table-footer"><span>${ts.length?`${(page-1)*10+1}–${Math.min(page*10,ts.length)} of ${ts.length}`:'0'} tasks</span><div>${btn('Previous','prev-page','small-button')}<span>Page ${page} of ${pages}</span>${btn('Next','next-page','small-button')}</div></div>`;}
function taskTable(ts,readOnly=false){if(!ts.length)return empty('You’re all caught up.','No tasks match this view.',btn('Create task','create-task','','plus'));const cols=['assignee','status','priority','complexity','deadline','hours','quality'].filter(c=>columns.has(c));return `<div class="table-scroll"><table class="data-table"><thead><tr><th><button data-sort="title">Task ${icon('down')}</button></th>${cols.map(c=>`<th><button data-sort="${c}">${c[0].toUpperCase()+c.slice(1)} ${icon('down')}</button></th>`).join('')}</tr></thead><tbody>${ts.map(t=>`<tr><td><button class="task-title" data-action="task:${t.id}"><span class="mono">TSK-${String(t.id).padStart(3,'0')}</span><strong>${esc(t.title)}</strong></button><div class="task-progress">${t.checklist.length?`<span>${t.checklist.filter(x=>x.done).length}/${t.checklist.length}</span><i><b style="width:${t.checklist.filter(x=>x.done).length/t.checklist.length*100}%"></b></i>`:'<span>No checklist</span>'}</div></td>${cols.map(c=>`<td>${c==='assignee'?`<span class="assignee">${avatar(person(t.assignee),'tiny-avatar')}<span>${esc(person(t.assignee).name.split(' ')[0])}</span></span>`:c==='status'?`<label class="inline-select">${status(t.status)}<select data-task-status="${t.id}" aria-label="Status for ${esc(t.title)}">${opt(S.statuses,t.status)}</select></label>`:c==='priority'?`<label class="inline-select">${priority(t.priority)}<select data-task-priority="${t.id}" aria-label="Priority for ${esc(t.title)}">${opt(S.priorities,t.priority)}</select></label>`:c==='complexity'?complexity(t.complexity):c==='deadline'?`<span class="${overdue(t)?'danger':''}">${fmt(t.deadline)}</span>`:c==='hours'?`${t.hours}h`:esc(t.quality||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function openOverlay(html,cls='',label='Dialog'){previousFocus=document.activeElement;$('#overlay').innerHTML=`<div class="scrim"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(label)}">${html}</section></div>`;requestAnimationFrame(()=>$('.modal input,.modal button,.modal select')?.focus());document.body.classList.add('modal-open');}
function closeOverlay(){document.body.classList.remove('modal-open');$('#overlay').innerHTML='';detail=null;previousFocus?.focus();}
const modalHead = (eyebrow,title) => `<div class="modal-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;
function createTask(){openOverlay(modalHead('TASK MANAGEMENT','Create a task')+`<form id="create-task-form"><div class="modal-body">${field('Task title',input('title','','text','required maxlength="200" placeholder="What needs to be done?"'))}${field('Description','<textarea name="description" rows="3" placeholder="Give your team the context they need…"></textarea>')}<div class="form-grid">${field('Assignee',select('assignee',S.users,S.me.id))}${field('Priority',select('priority',S.priorities,'Normal'))}${field('Complexity',select('complexity',S.complexities,'Medium'))}${field('Start date',input('start',S.today,'date','required'))}${field('Deadline',input('deadline','','date'))}<label class="check-field"><input name="review_required" type="checkbox" checked><span>Manager review required</span></label></div><details class="advanced"><summary>Additional details <span>Checklist & references</span></summary>${field('Work team',select('work_team',S.teams,'','Assignee’s primary team'))}<p class="small muted">Choose another work team for temporary assistance. The assignee’s primary team stays the same.</p>${field('Checklist','<textarea name="checklist" rows="3" placeholder="One item per line"></textarea>')}${field('External reference',input('reference','','url','placeholder="https://…"'))}<p class="small muted">Files can be attached after creating the task.</p></details><div class="form-error" role="alert"></div></div><div class="modal-footer">${btn('Cancel','close')}<button type="submit" class="button primary">Create task ${icon('arrow')}</button></div></form>`,'create-modal','Create task');}
function attachmentList(kind,id,slot=''){return S.attachments.filter(a=>a.kind===kind&&a.object_id===id&&a.slot===slot).map(a=>`<a class="attachment" href="/api/attachments/${a.id}">${icon('file')}<span>${esc(a.name)}</span>${icon('download')}</a>`).join('');}
function uploadButton(kind,id,slot='',label='Attach file'){return `<label class="button file-button">${icon('plus')}${label}<input type="file" data-upload="${kind}" data-id="${id}" data-slot="${slot}" aria-label="${label}"></label>`;}
function taskDetail(id){const t=S.tasks.find(t=>t.id===Number(id));if(!t)return;detail=t.id;const u=person(t.assignee);openOverlay(modalHead(`<span class="mono">TSK-${String(t.id).padStart(3,'0')}</span> <span class="text-separator">/</span> ${esc(u.team)}`,esc(t.title))+`<div class="detail-layout"><div class="detail-main"><div class="section-head"><h3>Description</h3>${btn('Edit','edit-description:'+t.id,'ghost small-button')}</div><p class="description">${esc(t.description||'No description yet.')}</p><div class="section-head"><h3>Checklist <span class="muted">${t.checklist.filter(x=>x.done).length}/${t.checklist.length}</span></h3>${btn('Add item','add-check:'+t.id,'ghost small-button','plus')}</div><div class="checklist">${t.checklist.map((x,i)=>`<label class="checklist-item ${x.done?'checked':''}"><input type="checkbox" data-check-task="${t.id}" data-index="${i}" ${x.done?'checked':''}><span>${esc(x.text)}</span></label>`).join('')||'<p class="muted small">Break work into a few clear steps.</p>'}</div><div class="section-head"><h3>Attachments</h3>${uploadButton('task',t.id)}</div>${attachmentList('task',t.id)||'<p class="muted small">No attachments yet · Up to 5 MB per file</p>'}${t.reference?`<a class="text-link" href="${esc(t.reference)}" target="_blank" rel="noopener noreferrer">${icon('link')}External reference</a>`:''}<h3 class="spaced">Comments</h3><div class="comments">${S.comments.filter(c=>c.task_id===t.id).map(c=>`<div class="comment">${avatar(person(c.user_id),'small-avatar')}<div><strong>${esc(person(c.user_id).name)}</strong><time>${new Date(c.created).toLocaleString('en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}${c.edited?' · Edited':''}</time><p>${esc(c.body)}</p>${c.user_id===S.me.id?btn('Edit','edit-comment:'+c.id,'ghost small-button'):''}</div></div>`).join('')||'<p class="muted small">Keep the conversation close to the work.</p>'}</div><form id="comment-form" data-task="${t.id}"><textarea name="body" rows="2" required placeholder="Write a comment… Use @Name to mention a teammate" aria-label="Comment"></textarea><div class="comment-actions">${uploadButton('task',t.id)}<button class="button small-button" type="submit">Post comment</button></div></form><h3 class="spaced">Activity</h3><div class="activity-feed">${S.events.filter(e=>e.task_id===t.id).slice(0,8).map(e=>`<p><i></i><span><strong>${esc(person(e.user_id).name.split(' ')[0])}</strong> · ${esc(e.body)}<small>${new Date(e.created).toLocaleString()}</small></span></p>`).join('')||'<p class="muted small">Changes to this task will appear here.</p>'}</div></div><aside class="context-panel"><h3>Properties</h3><div class="property"><span>Assignee</span><div class="assignee">${avatar(u,'small-avatar')}${esc(u.name)}</div></div>${field('Status',`<select data-task-status="${t.id}">${opt(S.statuses,t.status)}</select>`)}${field('Priority',`<select data-task-priority="${t.id}">${opt(S.priorities,t.priority)}</select>`)}${field('Complexity',`<select data-task-complexity="${t.id}">${opt(S.complexities,t.complexity)}</select>`)}<div class="property"><span>Work team</span><strong>${esc(t.work_team||u.team)}</strong></div><div class="property"><span>Deadline</span><strong class="${overdue(t)?'danger':''}">${fmt(t.deadline)}</strong></div>${field('Actual hours',`<input type="number" min="0" max="100000" step="0.25" value="${t.hours}" data-task-hours="${t.id}">`)}${S.me.role!=='Analyst'?field('Quality',`<select data-task-quality="${t.id}">${opt(S.qualities,t.quality,'Not evaluated')}</select>`):`<div class="property"><span>Quality</span><strong>${esc(t.quality||'Not evaluated')}</strong></div>`}<div class="property"><span>Review</span><strong>${t.review_required?'Manager approval required':'Not required'}</strong></div>${t.status==='Review'&&S.me.role!=='Analyst'?btn('Approve task','approve:'+t.id,'primary wide','check')+btn('Return task','return:'+t.id,'wide'):''}</aside></div>`,'detail-modal','Task details');detail=t.id;}
function shiftsPage(){if(route==='shifts/history')return shiftHistory();const s=S.shifts.find(s=>s.id===activeShift)||S.shifts.find(s=>s.user_id===S.me.id&&s.day===S.today);if(!s)return pageHead('SOC OPERATIONS','Shift workspace','Small, consistent actions. A complete picture of the day.',btn('Shift history','shift-history','','calendar'))+empty('No shift activity has been recorded for today.','Start your shift to capture routine activity, IOCs, and individual tickets.',S.me.team.startsWith('SOC')?btn('Start shift log','start-shift','primary','plus'):'')+shiftOverview();return shiftEditor(s);}
function shiftOverview(){return `<section class="panel">${sectionHead('Team shifts','Recent activity across your visible teams')}${shiftTable(S.shifts.slice(0,10))}</section>`;}
function shiftHistory(){return pageHead('SOC OPERATIONS','Shift log history','A reliable record of the routine work behind every shift.',btn('Today’s shift','today-shift','','shift'))+`<section class="panel"><div class="filter-bar">${field('From',input('history-start',range.start,'date'))}${field('To',input('history-end',range.end,'date'))}<div class="push"></div><span class="muted small">Select a shift to inspect its activities and ticket records.</span></div>${shiftTable(S.shifts.filter(s=>inRange(s.day)))}</section>`;}
function shiftTable(shifts){return shifts.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Analyst</th><th>Date</th><th>Status</th><th>Completion</th><th>IOCs</th><th>Tickets</th><th></th></tr></thead><tbody>${shifts.map(s=>`<tr><td><span class="assignee">${avatar(person(s.user_id),'small-avatar')}${esc(person(s.user_id).name)}</span></td><td>${fmt(s.day)}</td><td>${status(s.status)}</td><td>${s.activities.filter(a=>a.done).length} / 8 activities</td><td>${s.iocs}</td><td>${s.tickets.length}</td><td>${btn('Open','open-shift:'+s.id,'ghost','arrow')}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity was found for the selected period.','Try a different date range.');}
function shiftEditor(s){const count=s.activities.filter(a=>a.done).length,readOnly=s.status==='Completed'||s.user_id!==S.me.id, disabled=readOnly?'disabled':'';activeShift=s.id;return pageHead('SOC OPERATIONS',`Shift log <span class="muted">—</span> ${fmt(s.day)}, ${s.day.slice(0,4)}`,`${esc(person(s.user_id).name)} <span class="text-separator">/</span> ${status(s.status)} <span class="text-separator">/</span> Updated ${new Date(s.updated).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'})}`,btn('Shift history','shift-history','','calendar'))+`<div class="shift-layout"><section class="panel shift-activities">${sectionHead('The daily essentials',readOnly?'This shift is read-only.':'Check off completed activities. Add context only when it matters.',`<span class="completion-tag">${Math.round(count/8*100)}% complete</span>`)}<div class="thin-progress"><i style="width:${count/8*100}%"></i></div>${S.activities.map((title,i)=>{const a=s.activities[i];return `<article class="shift-activity ${a.done?'is-done':''}"><div class="activity-top"><label class="activity-check"><input type="checkbox" data-shift-check="${i}" ${a.done?'checked':''} ${disabled}><span>${icon('check')}</span></label><div><h3>${title}</h3><span class="small ${a.issue?'danger':'muted'}">${a.issue?'Issue reported: '+esc(a.issue.summary):a.done?'Completed — No Issue':'Not completed'}</span></div><span class="activity-number">${String(i+1).padStart(2,'0')}</span></div>${i===7?`<div class="misp-fields">${field('IOC count',`<input type="number" data-shift-iocs min="0" max="10000000" step="1" value="${s.iocs}" ${disabled}>`)}${field('Shared via Bale',`<select data-shift-shared ${disabled}>${opt([{id:'1',name:'Yes'},{id:'0',name:'No'}],s.shared)}</select>`)}${field('External reference',`<input type="url" data-shift-reference value="${esc(s.reference)}" placeholder="https://…" ${disabled}>`)}</div>`:''}<div class="activity-extras"><details ${a.note?'open':''}><summary>${icon('dots')} ${a.note?'View note':'Add a note'}</summary><textarea data-shift-note="${i}" rows="2" placeholder="Optional context for this activity…" ${disabled}>${esc(a.note)}</textarea></details>${[0,2,4,5,6].includes(i)&&!readOnly?btn(a.issue?'Edit issue':'Report an issue','issue:'+i,'ghost small-button'):''}${[1,3].includes(i)&&!readOnly?uploadButton('shift',s.id,String(i),i===3?'Attach report':'Attach files'):''}</div>${i===1?`<div class="activity-reference">${field('Files / external reference',`<input type="url" data-activity-reference="${i}" value="${esc(a.reference||'')}" placeholder="https://…" ${disabled}>`)}</div>`:''}${attachmentList('shift',s.id,String(i))}${a.issue?`<div class="issue-note"><strong>${esc(a.issue.summary)}</strong><p>${esc(a.issue.description)}</p>${a.issue.reference?`<a class="text-link" href="${esc(a.issue.reference)}" target="_blank" rel="noopener noreferrer">External reference ${icon('link')}</a>`:''}${!readOnly?uploadButton('shift',s.id,'issue-'+i,'Attach issue file'):''}${attachmentList('shift',s.id,'issue-'+i)}</div>`:''}</article>`;}).join('')}</section><aside class="shift-side"><section class="panel ticket-panel">${sectionHead('Created tickets',`${s.tickets.length} tickets registered`,readOnly?'':btn('Add ticket','add-ticket','small-button','plus'))}<p class="small muted">Capture each ticket number to keep the record traceable.</p><div class="ticket-list">${s.tickets.map((t,i)=>`<div class="ticket-record"><div><strong class="mono">${esc(t.number)}</strong>${readOnly?'':`<button class="icon-button" data-action="remove-ticket:${i}" aria-label="Remove ticket ${esc(t.number)}">${icon('close')}</button>`}</div><p>${esc(t.description||'No description')}</p><small>${esc(t.related)}</small>${t.link?`<a class="text-link" href="${esc(t.link)}" target="_blank" rel="noopener noreferrer">Open reference ${icon('link')}</a>`:''}</div>`).join('')||'<div class="small-empty">No tickets recorded yet.</div>'}</div></section><section class="panel shift-recap">${sectionHead('Your shift, at a glance')}<div><span>Activities completed</span><strong>${count} / 8</strong></div><div><span>IOCs added</span><strong>${s.iocs}</strong></div><div><span>Tickets created</span><strong>${s.tickets.length}</strong></div><div><span>Issues reported</span><strong>${s.activities.filter(a=>a.issue).length}</strong></div>${!readOnly?`<p class="small muted">${count===8?'All activities are complete. Your shift is ready to close.':`${8-count} activities remain. Complete the checklist before closing your shift.`}</p>${btn('Complete shift','complete-shift','primary wide','check')}`:`<p class="positive small">${icon('check')} ${s.status==='Completed'?'Shift completed and recorded':'Viewing team member’s shift'}</p>`}</section></aside></div>`;}
function teamPage(){return pageHead('PEOPLE & TEAMS','Your team, connected.','A shared view of responsibilities and current workload.',btn('View performance','go-performance','','chart'))+`<div class="team-summary">${S.teams.map(t=>`<div><span>${esc(t)}</span><strong>${S.users.filter(u=>u.team===t).length}<small> people</small></strong></div>`).join('')}</div><section class="panel">${sectionHead('Employee directory',`${S.users.length} people · Primary team and current responsibilities`)}<div class="table-scroll"><table class="data-table"><thead><tr><th>Employee</th><th>Role</th><th>Primary team</th><th>Current workload</th><th>Open tasks</th><th>Shift status</th><th></th></tr></thead><tbody>${S.users.map(u=>{const tasks=activeTasks(S.tasks.filter(t=>t.assignee===u.id)),shift=S.shifts.find(s=>s.user_id===u.id&&s.day===S.today);return `<tr><td><button class="employee-name" data-action="employee:${u.id}">${avatar(u)}<span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span></button></td><td>${esc(u.role)}</td><td>${esc(u.team)}</td><td><div class="workload"><i><b style="width:${Math.min(100,tasks.length*15)}%"></b></i><span>${tasks.length>5?'High':tasks.length?'Balanced':'Available'}</span></div></td><td>${tasks.length}</td><td>${u.team.startsWith('SOC')?status(shift?.status||'Not started'):'<span class="muted">—</span>'}</td><td>${btn('View','employee:'+u.id,'ghost','arrow')}</td></tr>`}).join('')}</tbody></table></div></section>`;}
function dateControls(){return `<select id="period" aria-label="Selected period">${opt(['This Month','Last Month','Quarter','Custom Range'],period)}</select>${period==='Custom Range'?`<input type="date" id="range-start" value="${range.start}" aria-label="Period start"><span>to</span><input type="date" id="range-end" value="${range.end}" aria-label="Period end">`:''}`;}
function performancePage(){const employee=route==='performance/employee',u=person(employeeId||S.me.id),ts=S.tasks.filter(t=>(!employee||t.assignee===u.id)&&inRange(t.completed||t.start)),ss=S.shifts.filter(s=>(!employee||s.user_id===u.id)&&inRange(s.day)),done=ts.filter(t=>t.status==='Done'),total=done.length;return pageHead('WORKFORCE PERFORMANCE',employee?esc(u.name):'The work behind the numbers.',employee?`${esc(u.role)} <span class="text-separator">/</span> ${esc(u.team)}`:'A thoughtful view of contribution. Tasks and routine activity, kept distinct.',dateControls()+btn('Export to Excel','export-performance','','download'))+`<div class="view-tabs"><button class="${employee?'':'selected'}" data-nav="performance">Overview</button><button class="${employee?'selected':''}" data-action="employee:${u.id}">Employee performance</button><div class="push"></div>${employee?`<select id="performance-employee" aria-label="Employee">${opt(S.users,u.id)}</select>`:`<span>${fmt(range.start)} – ${fmt(range.end)}, ${range.end.slice(0,4)}</span>`}</div>`+metrics([['Completed tasks',total,'Task work only','check'],['Task hours',ts.reduce((n,t)=>n+t.hours,0).toFixed(1),'Recorded actual hours','clock'],['Shift logs completed',ss.filter(s=>s.status==='Completed').length,'Routine work only','shift'],['MISP IOC count',ss.reduce((n,s)=>n+s.iocs,0),'Recorded in shift logs','plus'],['Tickets created',ss.reduce((n,s)=>n+s.tickets.length,0),'Individual ticket records','report']])+`<div class="performance-grid"><section class="panel">${sectionHead('Work complexity','Distribution of completed tasks')}<div class="complexity-bars">${S.complexities.map((c,i)=>{const n=done.filter(t=>t.complexity===c).length;return `<div><span>${c}</span><i><b class="complexity-${i}" style="width:${total?n/total*100:0}%"></b></i><strong>${n}</strong><small>${total?Math.round(n/total*100):0}%</small></div>`}).join('')}</div></section><section class="panel">${sectionHead('Routine activity','SOC shift contributions · counted separately',btn('View shift logs','shift-history','ghost','arrow'))}<div class="routine-stats"><div><strong>${ss.length?Math.round(ss.reduce((n,s)=>n+s.activities.filter(a=>a.done).length,0)/(ss.length*8)*100):0}%</strong><span>Routine completion</span></div><div><strong>${ss.filter(s=>s.activities[3].done).length}</strong><span>Daily traffic reports</span></div><div><button class="number-link" data-action="performance-tickets">${ss.reduce((n,s)=>n+s.tickets.length,0)} ${icon('arrow')}</button><span>Traceable tickets</span></div></div></section></div><section class="panel">${sectionHead('Task performance',`${ts.length} tasks in the selected period · ${employee?esc(u.name):'Visible teams'}`)}${performanceTable(ts)}</section>${!employee?`<section class="panel contribution-section">${sectionHead('Employee contributions','Explore an employee’s actual work. Listed alphabetically.')}<div class="contribution-list">${S.users.map(u=>`<button data-action="employee:${u.id}">${avatar(u)}<span><strong>${esc(u.name)}</strong><small>${esc(u.team)}</small></span><span class="muted">${done.filter(t=>t.assignee===u.id).length} completed tasks</span>${icon('arrow')}</button>`).join('')}</div></section>`:`<section class="panel contribution-section">${sectionHead('Daily shift records','Select a day to view activities and ticket numbers')}${shiftTable(ss)}</section>`}`;}
function performanceTable(ts){return ts.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Task / work description</th><th>Complexity</th><th>Quality</th><th>Start</th><th>End</th><th>Hours</th><th>Status</th></tr></thead><tbody>${ts.map(t=>`<tr><td><button class="task-title" data-action="task:${t.id}"><strong>${esc(t.title)}</strong></button><p class="table-description">${esc(t.description)}</p></td><td>${complexity(t.complexity)}</td><td>${esc(t.quality||'Not evaluated')}</td><td>${fmt(t.start)}</td><td>${fmt(t.completed)}</td><td>${t.hours}h</td><td>${status(t.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity was found for the selected period.','Choose another date range or employee.');}
const reportTypes=['Employee Monthly Report','Team Monthly Report','Task Report','SOC Shift Activity Report','Ticket Report'];
function reportsPage(){const ids=S.users.filter(u=>(!reportFilters.employee||u.id===+reportFilters.employee)&&(!reportFilters.team||u.team===reportFilters.team)).map(u=>u.id);const ts=S.tasks.filter(t=>ids.includes(t.assignee)&&inRange(t.completed||t.start)&&['status','complexity','quality'].every(k=>!reportFilters[k]||t[k]===reportFilters[k])),ss=S.shifts.filter(s=>ids.includes(s.user_id)&&inRange(s.day));return pageHead('REPORTING','From daily work to a clear report.','Practical reports, ready to share. Always grounded in recorded activity.',btn('Export to Excel','export-report','primary','download'))+`<div class="report-selector">${reportTypes.map((t,i)=>`<button data-report="${t}" class="${reportType===t?'selected':''}">${icon(['team','team','tasks','shift','report'][i])}<span>${t.replace(' Report','')}</span></button>`).join('')}</div><section class="panel"><div class="report-filters">${field('From',`<input type="date" id="report-start" value="${range.start}">`)}${field('To',`<input type="date" id="report-end" value="${range.end}">`)}${field('Employee',`<select data-report-filter="employee">${opt(S.users,reportFilters.employee,'All employees')}</select>`)}${field('Team',`<select data-report-filter="team">${opt(S.teams,reportFilters.team,'All teams')}</select>`)}${!['Ticket Report','SOC Shift Activity Report'].includes(reportType)?field('Status',`<select data-report-filter="status">${opt(S.statuses,reportFilters.status,'All statuses')}</select>`)+field('Complexity',`<select data-report-filter="complexity">${opt(S.complexities,reportFilters.complexity,'All complexity')}</select>`)+field('Quality',`<select data-report-filter="quality">${opt(S.qualities,reportFilters.quality,'All quality')}</select>`):''}${btn('Reset','reset-reports','ghost')}</div>${sectionHead(reportType,`${fmt(range.start)} – ${fmt(range.end)} · ${ids.length} employees`)}${reportType==='Ticket Report'?`<div class="filter-bar"><label class="search-input">${icon('search')}<input id="ticket-search" placeholder="Search ticket numbers, analysts, references…" value="${esc(reportFilters.q)}" aria-label="Search tickets"></label></div><div id="ticket-results">${ticketTable(ss,reportFilters.q)}</div>`:reportType==='SOC Shift Activity Report'?shiftTable(ss):performanceTable(ts)}${['Employee Monthly Report','Team Monthly Report'].includes(reportType)?`<div class="section-divider"></div>${sectionHead('Routine activity','Export includes separate sheets for tasks, routine activity, and ticket numbers.')}${shiftTable(ss)}`:''}</section>`;}
function ticketTable(ss,query=''){const rows=ss.flatMap(s=>s.tickets.map(t=>({...t,day:s.day,user_id:s.user_id}))).filter(t=>`${t.number} ${t.related} ${t.description} ${person(t.user_id).name}`.toLowerCase().includes(query.toLowerCase()));return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Analyst</th><th>Date</th><th>Ticket number</th><th>Related reference</th><th>Description</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(person(t.user_id).name)}</td><td>${fmt(t.day)}</td><td>${t.link?`<a class="mono text-link" href="${esc(t.link)}" target="_blank" rel="noopener noreferrer">${esc(t.number)} ${icon('link')}</a>`:`<span class="mono">${esc(t.number)}</span>`}</td><td>${esc(t.related||'—')}</td><td>${esc(t.description||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity was found for the selected period.','Tickets appear here as individual records when entered in a shift log.');}
function adminPage(){if(S.me.role!=='Security Manager')return empty('This view is available to Security Managers.');return pageHead('ADMINISTRATION','People, roles & access','Keep responsibilities clear and access appropriate.',btn('Add employee','add-user','primary','plus'))+`<div class="permission-summary"><div>${icon('team')}<strong>Analyst</strong><p>Own tasks, shift logs, and personal performance.</p></div><div>${icon('brief')}<strong>SOC Manager</strong><p>SOC teams, work allocation, review, and reporting.</p></div><div>${icon('settings')}<strong>Security Manager</strong><p>Department-wide visibility and user administration.</p></div></div><section class="panel">${sectionHead('User & role management','Role changes apply immediately. Other active sessions are signed out.')}<div class="table-scroll"><table class="data-table"><thead><tr><th>Employee</th><th>Email</th><th>Role</th><th>Primary team</th><th></th></tr></thead><tbody>${S.users.map(u=>`<tr><td><span class="assignee">${avatar(u,'small-avatar')}${esc(u.name)}</span></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${esc(u.team)}</td><td>${btn('Manage','manage-user:'+u.id,'ghost')}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function saveTask(id,changes){await api('tasks/'+id,'PATCH',changes);await refresh();if(detail)taskDetail(id);toast('Task updated');}
async function saveShift(changes,renderPage=true){await api('shifts/'+activeShift,'PATCH',changes);await refresh(renderPage);}
function currentShift(){return S.shifts.find(s=>s.id===activeShift);}
function editForm(title,fields,id,extra=''){openOverlay(modalHead('WORKSPACE',title)+`<form id="${id}" ${extra}><div class="modal-body">${fields}<div class="form-error" role="alert"></div></div><div class="modal-footer">${btn('Cancel','close')}<button class="button primary" type="submit">Save changes</button></div></form>`,'compact-modal',title);}
function exportReport(performance=false){const params=new URLSearchParams({start:range.start,end:range.end,type:performance?'Employee Monthly Report':reportType});if(performance&&route==='performance/employee')params.set('employee',employeeId||S.me.id);if(!performance)for(const k of ['employee','team','status','complexity','quality','q'])if(reportFilters[k])params.set(k,reportFilters[k]);window.location.href='/api/export?'+params.toString();toast('Preparing your Excel workbook');}
const actions={
 'reload':()=>location.reload(),'create-task':createTask,'close':closeOverlay,'retry':()=>refresh(),'go-tasks':()=>navigate('tasks/all'),'go-shifts':()=>navigate('shifts'),'go-performance':()=>navigate('performance'),
 'collapse':()=>{collapsed=!collapsed;localStorage.setItem('cadence-collapsed',collapsed?'1':'0');render();},
 'theme':()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('cadence-theme',document.documentElement.dataset.theme);render();},
 'logout':async()=>{await api('logout','POST',{});login();},
 'workspace':()=>toast('Security Department · '+S.users.length+' visible employees'),
 'reset-task-filters':()=>{taskFilter={q:'',status:'',priority:'',sort:'deadline',scope:'all'};page=1;render();},
 'columns':()=>openOverlay(modalHead('TABLE PREFERENCES','Visible columns')+`<div class="modal-body column-options">${['assignee','status','priority','complexity','deadline','hours','quality'].map(c=>`<label class="check-field"><input type="checkbox" data-column="${c}" ${columns.has(c)?'checked':''}><span>${c[0].toUpperCase()+c.slice(1)}</span></label>`).join('')}</div><div class="modal-footer">${btn('Done','close','primary')}</div>`,'compact-modal','Visible columns'),
 'prev-page':()=>{page=Math.max(1,page-1);$('#task-results').innerHTML=taskResults();},'next-page':()=>{page++;$('#task-results').innerHTML=taskResults();},
 'queue-all':()=>{$('#queue').innerHTML=queueRows(S.tasks.filter(t=>overdue(t)||['Review','Blocked'].includes(t.status)));$$('.tabs button').forEach((b,i)=>b.classList.toggle('selected',i===0));},
 'queue-review':()=>{$('#queue').innerHTML=queueRows(S.tasks.filter(t=>t.status==='Review'));$$('.tabs button').forEach((b,i)=>b.classList.toggle('selected',i===1));},
 'start-shift':async()=>{const r=await api('shifts','POST',{day:S.today});activeShift=r.id;await refresh(false);navigate('shifts');},
 'shift-history':()=>navigate('shifts/history'),'today-shift':()=>{activeShift=null;navigate('shifts');},
 'complete-shift':async()=>{await saveShift({status:'Completed'});toast('Your shift is complete. Thank you for the careful work.');},
 'add-ticket':()=>editForm('Register a ticket',field('Ticket number',input('number','','text','required placeholder="e.g. SD-1042"'))+field('Related alert / incident reference',input('related','','text','placeholder="External reference only"'))+field('Description','<textarea name="description" rows="2"></textarea>')+field('External link',input('link','','url','placeholder="https://…"')),'ticket-form'),
 'tickets':()=>{reportType='Ticket Report';navigate('reports');},
 'performance-tickets':()=>{const ss=S.shifts.filter(s=>inRange(s.day)&&(route!=='performance/employee'||s.user_id===+(employeeId||S.me.id)));openOverlay(modalHead('ROUTINE ACTIVITY','Registered ticket numbers')+ticketTable(ss),'ticket-modal','Ticket records');},
 'export-report':()=>exportReport(),'export-performance':()=>exportReport(true),
 'reset-reports':()=>{reportFilters={employee:'',team:'',status:'',complexity:'',quality:'',q:''};period='This Month';setRange();render();},
 'add-user':()=>editForm('Add an employee',field('Full name',input('name','','text','required'))+field('Work email',input('email','','email','required'))+field('Initial password',input('password','','password','required minlength="12" autocomplete="new-password"'))+field('Role',select('role',S.roles,'Analyst'))+field('Primary team',select('team',S.teams,S.teams[0])),'user-form'),
 'search':()=>{openOverlay(`<div class="command-search">${icon('search')}<input id="command-query" placeholder="Search tasks, people, or pages…" aria-label="Search workspace"><kbd>Esc</kbd></div><div id="command-results">${commandResults('')}</div>`,'command-modal','Search workspace');$('#command-query').focus();},
 'notifications':()=>{const tasks=S.tasks.filter(t=>t.assignee===S.me.id||t.status==='Review'),mentions=S.comments.filter(c=>c.body.toLowerCase().includes('@'+S.me.name.split(' ')[0].toLowerCase()));openOverlay(modalHead('YOUR WORKSPACE','Notifications')+`<div class="notification-list">${tasks.filter(t=>overdue(t)||['Review','Returned'].includes(t.status)).map(t=>`<button data-action="task:${t.id}">${icon(overdue(t)?'clock':'tasks')}<span><strong>${overdue(t)?'Deadline passed':t.status==='Review'?'Task awaiting review':'Task returned'}</strong><small>${esc(t.title)}</small></span>${icon('arrow')}</button>`).join('')}${mentions.map(c=>`<button data-action="task:${c.task_id}">${icon('mail')}<span><strong>Mentioned in a comment</strong><small>${esc(c.body)}</small></span></button>`).join('')||''}${!tasks.some(t=>overdue(t)||['Review','Returned'].includes(t.status))&&!mentions.length?empty('You’re all caught up.','No notifications need your attention.'):''}</div>`,'compact-modal','Notifications');}
};
function commandResults(query){const q=query.toLowerCase();return [...navs.filter(x=>x[2].toLowerCase().includes(q)).map(x=>`<button data-nav="${x[0]}">${icon(x[1])}<span>${x[2]}</span><small>Page</small></button>`),...S.tasks.filter(t=>t.title.toLowerCase().includes(q)).slice(0,6).map(t=>`<button data-action="task:${t.id}">${icon('tasks')}<span>${esc(t.title)}</span><small>Task</small></button>`),...S.users.filter(u=>u.name.toLowerCase().includes(q)).slice(0,4).map(u=>`<button data-action="employee:${u.id}">${avatar(u,'tiny-avatar')}<span>${esc(u.name)}</span><small>Employee</small></button>`)].join('')||'<p class="small-empty">No matching results.</p>';}
async function action(key){if(actions[key])return actions[key]();const [name,id]=key.split(':');
 if(name==='task')return taskDetail(+id);
 if(name==='employee'){employeeId=+id;return navigate('performance/employee');}
 if(name==='open-shift'){activeShift=+id;return navigate('shifts');}
 if(name==='approve'||name==='return')return saveTask(+id,{status:name==='approve'?'Done':'Returned'});
 if(name==='edit-description'){const t=S.tasks.find(t=>t.id===+id);return editForm('Edit task details',field('Title',input('title',t.title,'text','required'))+field('Description',`<textarea name="description" rows="5">${esc(t.description)}</textarea>`),'description-form',`data-id="${id}"`);}
 if(name==='add-check')return editForm('Add checklist item',field('Checklist item',input('text','','text','required maxlength="200"')),'check-form',`data-id="${id}"`);
 if(name==='edit-comment'){const c=S.comments.find(c=>c.id===+id);return editForm('Edit comment',field('Comment',`<textarea name="body" rows="4" required>${esc(c.body)}</textarea>`),'edit-comment-form',`data-id="${id}" data-task="${c.task_id}"`);}
 if(name==='remove-ticket'){const tickets=[...currentShift().tickets];tickets.splice(+id,1);await saveShift({tickets});toast('Ticket removed');return;}
 if(name==='issue'){const issue=currentShift().activities[+id].issue;return editForm('Report an issue',field('Issue summary',input('summary',issue?.summary||'','text','required'))+field('Description',`<textarea name="description" rows="3">${esc(issue?.description||'')}</textarea>`)+field('External reference',input('reference',issue?.reference||'','url')),'issue-form',`data-index="${id}"`);}
 if(name==='manage-user'){const u=person(id);return editForm('Manage '+esc(u.name),field('Role',select('role',S.roles,u.role))+field('Primary team',select('team',S.teams,u.team)),'manage-user-form',`data-id="${id}"`);}
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const report=e.target.closest('[data-report]');if(report){reportType=report.dataset.report;render();return;}const sort=e.target.closest('[data-sort]');if(sort&&$('#task-results')){taskFilter.sort=sort.dataset.sort;$('#task-results').innerHTML=taskResults();return;}if(e.target.classList.contains('scrim')){closeOverlay();return;}const a=e.target.closest('[data-action]');if(a){try{await action(a.dataset.action);}catch(err){toast(err.message,true);}}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='task-search'){taskFilter.q=el.value;page=1;$('#task-results').innerHTML=taskResults();}if(el.id==='command-query')$('#command-results').innerHTML=commandResults(el.value);if(el.id==='ticket-search'){reportFilters.q=el.value;const ss=S.shifts.filter(s=>inRange(s.day)&&(!reportFilters.employee||s.user_id===+reportFilters.employee)&&(!reportFilters.team||person(s.user_id).team===reportFilters.team));$('#ticket-results').innerHTML=ticketTable(ss,el.value);}});
// Serialize saves so rapid checklist changes cannot overwrite a newer shift update.
let saveQueue=Promise.resolve();
document.addEventListener('change',e=>{const el=e.target;saveQueue=saveQueue.then(async()=>{
 const taskProp=Object.keys(el.dataset).find(k=>['taskStatus','taskPriority','taskComplexity','taskHours','taskQuality'].includes(k));
 if(taskProp){const prop=taskProp.slice(4).toLowerCase();await saveTask(+el.dataset[taskProp],{[prop]:prop==='hours'?Number(el.value):el.value});}
 if(el.dataset.checkTask){const id=+el.dataset.checkTask;const checklist=structuredClone(S.tasks.find(t=>t.id===id).checklist);checklist[+el.dataset.index].done=el.checked;await saveTask(id,{checklist});}
 if(el.dataset.column){el.checked?columns.add(el.dataset.column):columns.delete(el.dataset.column);render();}
 if(el.id==='task-status'||el.id==='task-priority'){taskFilter[el.id.split('-')[1]]=el.value;page=1;$('#task-results').innerHTML=taskResults();}
 if(el.hasAttribute('data-shift-check')||el.hasAttribute('data-shift-note')){const activities=structuredClone(currentShift().activities),index=+(el.dataset.shiftCheck??el.dataset.shiftNote);if(el.hasAttribute('data-shift-check'))activities[index].done=el.checked;else activities[index].note=el.value;await saveShift({activities},el.hasAttribute('data-shift-check'));}
 if(el.hasAttribute('data-activity-reference')){const activities=structuredClone(currentShift().activities);activities[+el.dataset.activityReference].reference=el.value;await saveShift({activities},false);}
 if(el.hasAttribute('data-shift-iocs'))await saveShift({iocs:Number(el.value)});
 if(el.hasAttribute('data-shift-shared'))await saveShift({shared:el.value==='1'});
 if(el.hasAttribute('data-shift-reference'))await saveShift({reference:el.value},false);
 if(el.dataset.upload){const file=el.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose a file up to 5 MB.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('attachments','POST',{kind:el.dataset.upload,object_id:+el.dataset.id,slot:el.dataset.slot,name:file.name,content});await refresh();if(el.dataset.upload==='task')taskDetail(+el.dataset.id);toast('File attached');}
 if(el.id==='period'){period=el.value;if(period!=='Custom Range')setRange();render();}
 if(['range-start','range-end','report-start','report-end'].includes(el.id)||['history-start','history-end'].includes(el.name)){const key=(el.id||el.name).endsWith('start')?'start':'end';range[key]=el.value;if(range.start>range.end){toast('End date must follow start date.',true);return;}render();}
 if(el.id==='performance-employee'){employeeId=+el.value;render();}
 if(el.dataset.reportFilter){reportFilters[el.dataset.reportFilter]=el.value;render();}
 }).catch(err=>{toast(err.message,true);if(S)render();if(detail)taskDetail(detail);});});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),submit=$('button[type="submit"]',f);if(submit)submit.disabled=true;try{
 if(f.id==='login-form'){await api('login','POST',d);route='dashboard';location.hash=route;await refresh();return;}
 if(f.id==='create-task-form'){d.assignee=+d.assignee;d.review_required=!!d.review_required;d.checklist=d.checklist.split('\n').map(s=>s.trim()).filter(Boolean);const t=await api('tasks','POST',d);closeOverlay();await refresh();taskDetail(t.id);toast('Task created');}
 if(f.id==='comment-form'){await api('comments','POST',{...d,task_id:+f.dataset.task});await refresh();taskDetail(+f.dataset.task);toast('Comment posted');}
 if(f.id==='ticket-form'){await saveShift({tickets:[...currentShift().tickets,d]});closeOverlay();toast('Ticket registered');}
 if(f.id==='issue-form'){const activities=structuredClone(currentShift().activities);activities[+f.dataset.index].issue=d;await saveShift({activities});closeOverlay();toast('Issue recorded');}
 if(f.id==='description-form'){await api('tasks/'+f.dataset.id,'PATCH',d);await refresh();taskDetail(+f.dataset.id);toast('Task details updated');}
 if(f.id==='check-form'){const t=S.tasks.find(t=>t.id===+f.dataset.id);await api('tasks/'+t.id,'PATCH',{checklist:[...t.checklist,{text:d.text,done:false}]});await refresh();taskDetail(t.id);}
 if(f.id==='edit-comment-form'){await api('comments/'+f.dataset.id,'PATCH',d);await refresh();taskDetail(+f.dataset.task);}
 if(f.id==='user-form'){await api('users','POST',d);closeOverlay();await refresh();toast('Employee added');}
 if(f.id==='manage-user-form'){await api('users/'+f.dataset.id,'PATCH',d);closeOverlay();await refresh();toast('Employee access updated');}
 }catch(err){const error=$('.form-error',f);if(error)error.textContent=err.message;else toast(err.message,true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&S){e.preventDefault();actions.search();}if(e.key==='Escape')closeOverlay();const modal=$('.modal');if(e.key==='Tab'&&modal){const focusables=$$('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href],summary',modal).filter(x=>x.offsetParent!==null),first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{if(S&&location.hash.slice(1)!==route){route=location.hash.slice(1)||'dashboard';closeOverlay();render();}});
(async()=>{try{await refresh();}catch(e){if(e.message==='Please sign in to continue.')login();else{$('#app').innerHTML=`<main class="initial">${empty('Your workspace couldn’t be reached.','Check your connection and try again.',btn('Retry','reload','primary'))}</main>`;}}})();
